package com.quicktiles;

import java.awt.Color;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

/**
 * A saved tile placed in the loaded scene. Inside instances one saved tile can appear at a different
 * spot (or several), so this holds the scene's coordinates rather than the saved ones.
 */
final class MarkedTile
{
	private final WorldPoint point;
	@Nullable
	private final Color color;
	@Nullable
	private final String label;
	@Nullable
	private final String note;

	MarkedTile(WorldPoint point, @Nullable Color color, @Nullable String label)
	{
		this(point, color, label, null);
	}

	MarkedTile(WorldPoint point, @Nullable Color color, @Nullable String label, @Nullable String note)
	{
		this.point = point;
		this.color = color;
		this.label = label;
		this.note = note;
	}

	WorldPoint getPoint()
	{
		return point;
	}

	@Nullable
	Color getColor()
	{
		return color;
	}

	@Nullable
	String getLabel()
	{
		return label;
	}

	@Nullable
	String getNote()
	{
		return note;
	}
}

